import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:yoclip_core/yoclip_core.dart';

void main() {
  final outputFile = Platform.environment['YOCLIP_OUTPUT'];
  final frameEnv = Platform.environment['YOCLIP_FRAME'];

  final externalImageBytes = <String, Uint8List>{
    for (final e in {"logo":"","logo_on_light":"","golden_hook":"","golden_monolith":"","golden_kaleido":"","golden_space":"","golden_rally":"","golden_tunnel":"","ridge_far":"","ridge_mid":"","ridge_near":""}.entries)
      e.key: base64Decode(e.value as String),
  };

  testWidgets(
    'yoclip screenshot',
    (tester) async {
      if (outputFile == null || frameEnv == null) return;
      const projectPath = '.';
      final frame = int.parse(frameEnv);
      print('SCREENSHOT: output=$outputFile frame=$frame');

      final storage = LocalFileSystemStorage(projectPath);
      print('SCREENSHOT: loading project');
      final project = await YoclipProject.load(storage, projectPath);
      print('SCREENSHOT: project loaded');

      final runtime = createYoclipJsRuntime();
      print('SCREENSHOT: init runtime');
      await runtime.init();
      print('SCREENSHOT: runtime init done');
      addTearDown(runtime.dispose);

      final variant = project.config.variants.firstWhere(
        (v) => v.id == "dark_en",
        orElse: () => throw StateError(
          'Unknown variant "dark_en". Available: ${project.config.variants.map((v) => v.id).join(', ')}',
        ),
      );
      final scenes = await loadYoclipProjectScenes(runtime, project, storage, variant: variant);
      print('SCREENSHOT: scenes loaded');

      final targetScenes = scenes;

      final renderer = YoclipV2Renderer(
        project: applyVariantResolution(project, variant),
        scenes: targetScenes,
        storage: storage,
        externalFiles: {"logo":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/logo/yoclip_logo.svg","logo_on_light":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/logo_on_light/yoclip_logo_on_light.svg","golden_hook":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/golden_hook/hook.png","golden_monolith":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/golden_monolith/monolith.png","golden_kaleido":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/golden_kaleido/kaleido.png","golden_space":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/golden_space/space.png","golden_rally":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/golden_rally/rally.png","golden_tunnel":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/golden_tunnel/tunnel.png","ridge_far":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/ridge_far/ridge_far.svg","ridge_mid":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/ridge_mid/ridge_mid.svg","ridge_near":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea_v2/.yoclip_cache/external/ridge_near/ridge_near.svg"},
        externalFrameDirs: {},
        externalImageBytes: externalImageBytes,
      );

      final framesEnv = Platform.environment['YOCLIP_FRAMES'];
      final outDir = Platform.environment['YOCLIP_OUTDIR'] ?? '.';
      final frames = framesEnv == null || framesEnv.isEmpty
          ? [frame]
          : framesEnv.split(',').map(int.parse).toList();
      for (final f in frames) {
        print('SCREENSHOT: capturing frame $f');
        final bytes = await renderer.capturePng(tester, f);
        final out = '$outDir/f' + f.toString().padLeft(4, '0') + '.png';
        await tester.runAsync(() => File(out).writeAsBytes(bytes));
        stdout.writeln('Screenshot saved to $out');
      }
    },
    skip: frameEnv == null,
  );
}
